(5876253, 855672, 49716, '<td valign="top">Well focussed and exposed, but a bit of a ''snap'' for me.</td>', 'Well focussed and exposed, but a bit of a ''snap'' for me.', '2010-02-22 07:23:13.000000', NULL, 1),
(5876256, 855820, 49716, '<td valign="top">I like that this tells a story, even without reading the title.  The B&amp;W conversion is well done, but I''m not sure it helps to separate the ''clothing'' from the shoe.  Were they the wrong colours?</td>', 'I like that this tells a story, even without reading the title.  The B&W conversion is well done, but I''m not sure it helps to separate the ''clothing'' from the shoe.  Were they the wrong colours?', '2010-02-22 07:24:57.000000', NULL, 1),
(5876259, 855476, 49716, '<td valign="top">Clever thought on this one.  Maybe a different  set-up where the use of feet was even more essential would have been more powerful.</td>', 'Clever thought on this one.  Maybe a different  set-up where the use of feet was even more essential would have been more powerful.', '2010-02-22 07:26:38.000000', NULL, 1),
(5876260, 855781, 49716, '<td valign="top">Good use of depth of field and framing.  Not an image thing, but does the title match the image?  maybe ther track is no longer in use :-)</td>', 'Good use of depth of field and framing.  Not an image thing, but does the title match the image?  maybe ther track is no longer in use :-)', '2010-02-22 07:28:05.000000', NULL, 1),
(5876263, 855631, 49716, '<td valign="top">Cute.  I''m not sure if it it my monitor, but there appears to be sharpening artefacts around the edges of the booties.</td>', 'Cute.  I''m not sure if it it my monitor, but there appears to be sharpening artefacts around the edges of the booties.', '2010-02-22 07:29:46.000000', NULL, 1),
