(5876432, 854955, 49716, '<td valign="top">Intersting angle.  Not many images from this challenge looked UNDER the shoes.</td>', 'Intersting angle.  Not many images from this challenge looked UNDER the shoes.', '2010-02-22 09:35:30.000000', NULL, 1),
(5876436, 855839, 49716, '<td valign="top">Well though out and lots of preparation to pull this off I''m sure.  If there was a leg in the boot it might have been even better.</td>', 'Well though out and lots of preparation to pull this off I''m sure.  If there was a leg in the boot it might have been even better.', '2010-02-22 09:37:00.000000', NULL, 1),
