(5876442, 855851, 49716, '<td valign="top">I really like the lighting and feel of this one.  As the hands are so prominent I feel the need for them to be the point of focus not the toes.</td>', 'I really like the lighting and feel of this one.  As the hands are so prominent I feel the need for them to be the point of focus not the toes.', '2010-02-22 09:41:44.000000', NULL, 1),
(5876444, 854869, 49716, '<td valign="top">Not sure the border helps with this capture.</td>', 'Not sure the border helps with this capture.', '2010-02-22 09:42:11.000000', NULL, 1),
