(5876447, 855267, 49716, '<td valign="top">Simple, but effective.</td>', 'Simple, but effective.', '2010-02-22 09:43:33.000000', NULL, 1),
(5876450, 855086, 49716, '<td valign="top">Too much processing for my taste.  This was probably a good image before all the Photoshop work on it</td>', 'Too much processing for my taste.  This was probably a good image before all the Photoshop work on it', '2010-02-22 09:44:55.000000', NULL, 1),
(5876475, 855677, 49716, '<td valign="top">Very original concept.  I almost expect the image to animate and the boots to ''walk'' away!</td>', 'Very original concept.  I almost expect the image to animate and the boots to ''walk'' away!', '2010-02-22 10:00:55.000000', NULL, 1),
(5876492, 855848, 15711, '<td valign="top">This is adorable. I love the striped tights. The black pink theme works together so well.</td>', 'This is adorable. I love the striped tights. The black pink theme works together so well.', '2010-02-22 10:10:24.000000', NULL, 1),
(5876493, 854339, 15711, '<td valign="top">With all of the colors, it''s a bit busy for me.  I think neutralizing it would be to go black and white but that''s just me.</td>', 'With all of the colors, it''s a bit busy for me.  I think neutralizing it would be to go black and white but that''s just me.', '2010-02-22 10:10:55.000000', NULL, 1),
(5876494, 855685, 15711, '<td valign="top">Interesting and unexpected perspective.  I think a BW conversion with contrast adjustments would really give it some pop. I like the diagonal lines. :)</td>', 'Interesting and unexpected perspective.  I think a BW conversion with contrast adjustments would really give it some pop. I like the diagonal lines. :)', '2010-02-22 10:11:25.000000', NULL, 1),
(5876496, 855193, 15711, '<td valign="top">I like the old fashioned feel but I''d straight it out to make the risers parallel with the bottom of the image.  I guess if you did that then the banister might be wrong though. Hmmmmm.</td>', 'I like the old fashioned feel but I''d straight it out to make the risers parallel with the bottom of the image.  I guess if you did that then the banister might be wrong though. Hmmmmm.', '2010-02-22 10:12:25.000000', NULL, 1),
(5876497, 854693, 15711, '<td valign="top">Cute idea. I''d like this in BW better but that''s just me.</td>', 'Cute idea. I''d like this in BW better but that''s just me.', '2010-02-22 10:12:43.000000', NULL, 1),
(5876499, 855403, 15711, '<td valign="top">Cute idea.  Seems a touch over sharpened.  Maybe not being so close to the background?  I find the texture of the wall a bit distracting. :)</td>', 'Cute idea.  Seems a touch over sharpened.  Maybe not being so close to the background?  I find the texture of the wall a bit distracting. :)', '2010-02-22 10:15:36.000000', NULL, 1),
(5876500, 855361, 49716, '<td valign="top">Really like the lighting and composition of this image.  I would have been happy to see it without red toenails though, as they drag my eye too strongly to that section of the frame.</td>', 'Really like the lighting and composition of this image.  I would have been happy to see it without red toenails though, as they drag my eye too strongly to that section of the frame.', '2010-02-22 10:15:45.000000', NULL, 1),
(5876502, 855361, 15711, '<td valign="top">The selective saturation really works.  Love the skirt.</td>', 'The selective saturation really works.  Love the skirt.', '2010-02-22 10:16:14.000000', NULL, 1),
(5876504, 855743, 49716, '<td valign="top">Good concept, but not sharp or ''punchy'' enough to rate highly on DPC I think.</td>', 'Good concept, but not sharp or ''punchy'' enough to rate highly on DPC I think.', '2010-02-22 10:17:04.000000', NULL, 1),
(5876505, 855527, 15711, '<td valign="top">I like the blur.</td>', 'I like the blur.', '2010-02-22 10:17:23.000000', NULL, 1),
(5876506, 855461, 15711, '<td valign="top">I''d not have included the bottle of nail polish.  To me it pulls my eye away from the shoes.  Love the DOF.</td>', 'I''d not have included the bottle of nail polish.  To me it pulls my eye away from the shoes.  Love the DOF.', '2010-02-22 10:17:46.000000', NULL, 1),
(5876507, 855667, 49716, '<td valign="top">Great subject and B&amp;W conversion.  I''m not sure I need the reflection though.</td>', 'Great subject and B&W conversion.  I''m not sure I need the reflection though.', '2010-02-22 10:19:17.000000', NULL, 1),
(5876508, 855658, 15711, '<td valign="top">You just can''t get more classic than Chuck Taylors.  I like the contrast and slight hint of green in the BW conversion.</td>', 'You just can''t get more classic than Chuck Taylors.  I like the contrast and slight hint of green in the BW conversion.', '2010-02-22 10:19:33.000000', NULL, 1),
(5876518, 855486, 114826, '<td valign="top">This is really great, but you probably should have made the background more foggy. Its my favorite though!</td>', 'This is really great, but you probably should have made the background more foggy. Its my favorite though!', '2010-02-22 10:35:37.000000', NULL, 1),
(5876530, 855851, 57525, '<td valign="top">like the darkness</td>', 'like the darkness', '2010-02-22 10:41:18.000000', NULL, 1),
(5876578, 855384, 113278, '<td valign="top">I think you did a great job setting this up. It looks good and is well lit. But, I don''t like the light behind the boots. still a 7 imho.</td>', 'I think you did a great job setting this up. It looks good and is well lit. But, I don''t like the light behind the boots. still a 7 imho.', '2010-02-22 11:33:11.000000', NULL, 1),
(5876580, 855361, 109541, '<td valign="top">I like the composition and I like the color treatment.  Nicely done b&amp;w conversion also.</td>', 'I like the composition and I like the color treatment.  Nicely done b&w conversion also.', '2010-02-22 11:34:27.000000', NULL, 1),
(5876582, 855550, 109541, '<td valign="top">I like the colors and the reflection is well done.  I think I would have liked this better if the shoes were not both in the same straight line.  Nicely done photo.</td>', 'I like the colors and the reflection is well done.  I think I would have liked this better if the shoes were not both in the same straight line.  Nicely done photo.', '2010-02-22 11:35:50.000000', NULL, 1),
(5876584, 855659, 109541, '<td valign="top">Fun photo.  Creative idea.  Might want to pump up the b&amp;w a bit (a LITTLE bit).</td>', 'Fun photo.  Creative idea.  Might want to pump up the b&w a bit (a LITTLE bit).', '2010-02-22 11:37:39.000000', NULL, 1),
(5876586, 855848, 109541, '<td valign="top">Love the colors and the shoes with the socks.  The bench at the top really bothers me for composition.  I think cropping this just a bit from the top would make this work much better.  Neat lighting by the way.</td>', 'Love the colors and the shoes with the socks.  The bench at the top really bothers me for composition.  I think cropping this just a bit from the top would make this work much better.  Neat lighting by the way.', '2010-02-22 11:38:53.000000', NULL, 1),
(5876588, 855707, 109541, '<td valign="top">I like this guy already !!  Nice shot, nice lighting.  You could move your subjects head to a 1/3 quadrant and improve the composition just a bit, for me.  Thanks for not over editing this nice photo !!</td>', 'I like this guy already !!  Nice shot, nice lighting.  You could move your subjects head to a 1/3 quadrant and improve the composition just a bit, for me.  Thanks for not over editing this nice photo !!', '2010-02-22 11:41:18.000000', NULL, 1),
(5876591, 855839, 109541, '<td valign="top">Really creative photo.  Would like to see the roller blade just a bit brighter to contrast the background more.  This would be interesting on a sheet of black plastic, make sure you have your fire extinguisher !!!</td>', 'Really creative photo.  Would like to see the roller blade just a bit brighter to contrast the background more.  This would be interesting on a sheet of black plastic, make sure you have your fire extinguisher !!!', '2010-02-22 11:44:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5876592, 855631, 109541, '<td valign="top">Very pretty.  Nice use of colors, sharpness.  No crazy editing, just a well done photo with some nice post processing.  Well done !!!</td>', 'Very pretty.  Nice use of colors, sharpness.  No crazy editing, just a well done photo with some nice post processing.  Well done !!!', '2010-02-22 11:46:35.000000', NULL, 1),
