INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5884227, 855361, 102534, '<td valign="top">Congrats on finishing in the top 10. This was my fav shot of the challenge. Agree it should have ribboned.</td>', 'Congrats on finishing in the top 10. This was my fav shot of the challenge. Agree it should have ribboned.', '2010-03-01 01:10:36.000000', NULL, 0),
(5884247, 855667, 98022, '<td valign="top">Congrats on the blue Jeb! Great job on this image.</td>', 'Congrats on the blue Jeb! Great job on this image.', '2010-03-01 01:20:39.000000', NULL, 0),
(5884256, 855542, 112635, '<td valign="top">thank you for the votes!! 46th place ain''t that bad. this is one of my favorite entries ever.</td>', 'thank you for the votes!! 46th place ain''t that bad. this is one of my favorite entries ever.', '2010-03-01 01:24:14.000000', NULL, 0),
(5884259, 855667, 45631, '<td valign="top">Joke or not - fabulous pic and nice BW conversion.  Congratulations on the Blue.</td>', 'Joke or not - fabulous pic and nice BW conversion.  Congratulations on the Blue.', '2010-03-01 01:26:30.000000', NULL, 0),
(5884266, 855677, 45631, '<td valign="top">Love this shot - what a clever and creative idea.</td>', 'Love this shot - what a clever and creative idea.', '2010-03-01 01:30:04.000000', NULL, 0),
(5884277, 855667, 97166, '<td valign="top">chipuc sort of touched on it, and I think that it''s something that most voters didn''t even consciously REALIZE, even if it most likely sub-consciously affected them, but this shot actually anthropomorphizes these boots, making them seem a little alive, like they have mouths open in laughter, full of teeth.  This gives a static shot something more, and probably helped the audience connect to it.</td>', 'chipuc sort of touched on it, and I think that it''s something that most voters didn''t even consciously REALIZE, even if it most likely sub-consciously affected them, but this shot actually anthropomorphizes these boots, making them seem a little alive, like they have mouths open in laughter, full of teeth.  This gives a static shot something more, and probably helped the audience connect to it.', '2010-03-01 01:36:22.000000', NULL, 0),
(5884294, 855767, 45631, '<td valign="top">Love the framing and processing liberty - Congrats on the ribbon.</td>', 'Love the framing and processing liberty - Congrats on the ribbon.', '2010-03-01 01:41:07.000000', NULL, 0),
(5884307, 855667, 96751, '<td valign="top">Simply wonderful Jeb.  Congrats.</td>', 'Simply wonderful Jeb.  Congrats.', '2010-03-01 01:49:56.000000', NULL, 0),
(5884311, 855767, 96751, '<td valign="top">Terrific shot!  Congrats.</td>', 'Terrific shot!  Congrats.', '2010-03-01 01:51:31.000000', NULL, 0),
(5884314, 855667, 106543, '<td valign="top">Jeb I really liked this! In the Team Suck thread you said it wasn''t that great, I think you were just too critical of your own photo.The black and white looks great, that reflection is perfect and I feel that the background being full of stuff actually adds to this. Congratulations!<br/></td>', 'Jeb I really liked this! In the Team Suck thread you said it wasn''t that great, I think you were just too critical of your own photo.The black and white looks great, that reflection is perfect and I feel that the background being full of stuff actually adds to this. Congratulations!', '2010-03-01 01:55:24.000000', NULL, 0),
(5884316, 855361, 96751, '<td valign="top">I join the chorus of those who thought it should have placed higher.  This is a perfect picture in my eyes.  Congrats on the top 10.</td>', 'I join the chorus of those who thought it should have placed higher.  This is a perfect picture in my eyes.  Congrats on the top 10.', '2010-03-01 01:56:25.000000', NULL, 0),
(5884329, 855465, 47541, '<td valign="top">Greetings from the Critique Club.<br/> <br/><b>First impressions</b> are of a great sense of scale.<br/> <br/><b>Technically</b> this is ok. There are a few areas that show the lighting could be a bit softer - the front of the car and up near the shoelaces - I see you used a softbox though - hmmm. The show has cast quite a big shadow that cuts right through the car. Composition is good and the DOF seems excellent.<br/> <br/><b>Artistically</b> this is good. Humor is often not rewarded at DPC. As commenters have mentioned, the POV could be adjusted to add a sense of drama too - maybe lower and more front on to the car?<br/> <br/><b>In summary</b> a good solid shot that I''d have rated a bit closer to 6 than it scored.<br/> <br/>Feel free to <a href="//www.dpchallenge.com/messaging.php?action=compose&amp;USER_ID=47541" rel="nofollow" target="_blank">PM me</a> if you have any queries.<br/>Gerry</td>', 'Greetings from the Critique Club. First impressions are of a great sense of scale. Technically this is ok. There are a few areas that show the lighting could be a bit softer - the front of the car and up near the shoelaces - I see you used a softbox though - hmmm. The show has cast quite a big shadow that cuts right through the car. Composition is good and the DOF seems excellent. Artistically this is good. Humor is often not rewarded at DPC. As commenters have mentioned, the POV could be adjusted to add a sense of drama too - maybe lower and more front on to the car? In summary a good solid shot that I''d have rated a bit closer to 6 than it scored. Feel free to PM me if you have any queries.Gerry', '2010-03-01 02:06:15.000000', NULL, 0),
(5884331, 855781, 106109, '<td valign="top">Your DOF and low POV makes this photo work great.</td>', 'Your DOF and low POV makes this photo work great.', '2010-03-01 02:10:43.000000', NULL, 0),
